insert into public.learning_rules (id, title, tag, icon, formula) values
('rule_phap_bien_chung_3_quy_luat', '3 Quy luật biện chứng (Nguồn gốc - Cách thức - Khuynh hướng)', '3 Quy luật cốt lõi', '⚖️', 'Nguồn gốc/Động lực ➔ Mâu thuẫn | Cách thức/Hình thức ➔ Lượng - Chất | Khuynh hướng kế thừa/Đi lên ➔ Phủ định của phủ định'),
('rule_llsx_qhsx', 'Lực lượng sản xuất (LLSX) & Quan hệ sản xuất (QHSX)', 'Kinh tế & Xã hội', '⚙️', 'Cách mạng/động nhất ➔ Công cụ LĐ | Quyết định nhất/chủ thể ➔ Người LĐ | Nội dung ➔ LLSX, Hình thức ➔ QHSX | QHSX tác động ➔ Thúc đẩy hoặc kìm hãm'),
('rule_vat_chat_y_thuc', 'Vật chất, Ý thức & Tiêu chuẩn Chân lý', 'Bản thể & Nhận thức', '💡', 'Vật chất ➔ Thực tại khách quan (Lênin) | Ý thức ➔ Hình ảnh chủ quan của thế giới khách quan | Cơ sở/Động lực/Mục đích/Tiêu chuẩn chân lý ➔ Thực tiễn'),
('rule_csht_kttt', 'Tồn tại XH - Ý thức XH & Cơ sở hạ tầng - Kiến trúc thượng tầng', 'Duy vật lịch sử', '🏛️', 'Tồn tại XH quyết định Ý thức XH (Ý thức XH độc lập tương đối) | Cơ sở hạ tầng = Toàn bộ QHSX hợp thành cơ cấu kinh tế | KTTT = Thiết chế chính trị (Nhà nước tác động mạnh nhất)'),
('rule_cap_pham_tru', 'Các cặp phạm trù biện chứng (Riêng-Chung, Nhân-Quả, Tất nhiên-Ngẫu nhiên...)', 'Cặp phạm trù', '🔄', 'Cái chung chỉ tồn tại TRONG cái riêng | Cái riêng phong phú, toàn bộ hơn | Tất nhiên do nguyên nhân bên trong quyết định | Hiện tượng là biểu hiện bên ngoài của bản chất'),
('rule_tac_gia_triet_hoc', 'Tác giả, Tác phẩm & Tiền đề lý luận', 'Nhân vật & Lịch sử triết', '📚', 'Mác kế thừa: Phép biện chứng Hêghen + Duy vật Phoiơbắc | Lênin: ''Chủ nghĩa duy vật & chủ nghĩa kinh nghiệm phê phán'' | 3 bộ phận: Triết học + KTCT + CNXHKH'),
('rule_giai_cap_quan_chung_lich_su', 'Giai cấp, Quần chúng nhân dân & Đấu tranh xã hội', 'Chính trị - Xã hội', '👥', 'Chủ thể chân chính sáng tạo lịch sử ➔ Quần chúng nhân dân | Nguồn gốc phân chia giai cấp ➔ Kinh tế (chế độ tư hữu) | Động lực phát triển XH có giai cấp ➔ Đấu tranh giai cấp'),
('rule_van_dong_khong_gian', 'Vận động, Đứng im & Tính thống nhất thế giới', 'Hình thức tồn tại', '🌀', 'Vận động là tuyệt đối, vĩnh viễn | Đứng im là tương đối, tạm thời (trong cân bằng) | 5 hình thức vận động (Cơ - Lý - Hóa - Sinh - Xã hội; Cơ học là thấp nhất)'),
('rule_truong_phai_triet_hoc', 'Các trường phái Triết học (Duy vật - Duy tâm - Khả tri - Bất khả tri)', 'Trường phái & Vấn đề cơ bản', '🧭', 'Vấn đề cơ bản gồm 2 mặt (Mặt 1: Bản thể luận / cái nào có trước; Mặt 2: Nhận thức luận / có nhận thức được không) | Duy tâm khách quan (Thượng đế/Ý niệm) vs Duy tâm chủ quan (Cảm giác) | Khả tri (Biết được) vs Bất khả tri (Không thể biết)'),
('rule_kinh_te_chinh_tri', 'Kinh tế chính trị Mác - Lênin & Tư bản', 'Kinh tế chính trị bổ trợ', '💰', 'Thời gian chu chuyển = Thời gian SX + Thời gian lưu thông | Thặng dư tuyệt đối = Kéo dài ngày lao động | Thặng dư tương đối = Rút ngắn thời gian lao động tất yếu nhờ tăng năng suất LĐ')
